package com.example.swarmhunter
import com.example.swarmhunter.game.*
import org.junit.Assert.*
import org.junit.Test
class ExperienceRulesTest {
 @Test fun initialMuzzleTravelConsumesPulseRange(){val m=launchedMotion(V3(0f,0f,-1f),7f);assertEquals(.17f,m.travelled,.0001f);m.advance(.4f,3f-m.travelled);assertEquals(3f,m.travelled,.0001f)}
 @Test fun oldMissesAreRetiredButAggregateAccuracyRemains(){val e=HuntEngine();e.start();val old=e.recordShot();var recent=0;repeat(1000){recent=e.recordShot()};assertFalse(e.creditShot(old));assertTrue(e.creditShot(recent));assertEquals(1001,e.shotsFired);assertEquals(1,e.shotsHit)}
 @Test fun feedbackReflectsTheLatestDamageInsteadOfAnEarlierKill(){val f=HitFeedback();f.record(HitOutcome.KILLED,10f);assertTrue(f.killed);f.record(HitOutcome.DAMAGED,10.1f);assertFalse(f.killed);assertTrue(f.active(10.2f));assertFalse(f.active(10.4f))}
 @Test fun validatedExposedContactIsNotDiscardedByCenterOcclusion(){val r=RoomSurfaceRegistry();r.replace(listOf(RoomSurface("wall",RoomSurfaceKind.WALL,V3(0f,0f,-.5f),Q4(0f,0f,0f,1f),listOf(V3(-2f,-2f,0f),V3(2f,-2f,0f),V3(0f,2f,0f)),listOf(0,1,2))));val targets=listOf(2 to V3(0f,0f,-.55f),3 to V3(.3f,0f,-.7f));assertEquals(listOf(2),areaTargets(V3(0f,0f,-.25f),1.1f,targets,r,contactId=2))}
 @Test fun oldMissionShotIdsCannotCreditTheNewMission(){val e=HuntEngine();e.start();val old=e.recordShot();e.start();val current=e.recordShot();assertFalse(e.creditShot(old));assertTrue(e.creditShot(current));assertEquals(1,e.shotsHit)}
 @Test fun gradeThresholdsRequireKillsAndCombatPerformance(){
  val e=HuntEngine();e.start();repeat(25){val shot=e.recordShot();val t=e.spawn(0,V3(0f,0f,-2f));e.reveal(t.id);e.hit(t.id,2);e.creditShot(shot)}
  assertEquals("A",e.grade());e.tick(80f);assertEquals("S",e.grade())
  e.start();e.tick(5000f);assertEquals("C",e.grade())
 }
 @Test fun practiceToolsRemainVisibleOnlyWithEquippedTrackedHands(){assertTrue(toolVisible(HuntPhase.PRACTICE,true,true));assertFalse(toolVisible(HuntPhase.PRACTICE,true,false));assertFalse(toolVisible(HuntPhase.PRACTICE,false,true))}
 @Test fun idleSurvivalCannotEarnACombatRank(){val e=HuntEngine();e.start();e.tick(1000f);assertEquals("C",e.grade())}
 @Test fun unobservedTargetsRemindThenRecycleButVisibleOnesStay(){assertEquals(HiddenAction.REMIND,hiddenAction(6f,false,0,17f));assertEquals(HiddenAction.NONE,hiddenAction(7f,false,1,17f));assertEquals(HiddenAction.REMIND,hiddenAction(11f,false,1,17f));assertEquals(HiddenAction.RECYCLE,hiddenAction(18f,false,2,17f));assertEquals(HiddenAction.NONE,hiddenAction(100f,true,0,17f))}
 @Test fun recyclingDoesNotAwardKillsOrLeaveCapacityOccupied(){val e=HuntEngine();e.start();val a=e.spawn(0,V3(0f,0f,-2f));assertTrue(e.retireHidden(a.id));assertTrue(e.threats.isEmpty());assertEquals(0,e.kills);val b=e.spawn(0,V3(0f,0f,-2f));e.reveal(b.id);assertFalse(e.retireHidden(b.id))}
 @Test fun difficultyRampsAndRestsAreBounded(){val easy=encounterSettings(HuntDifficulty.RELAXED,0f);val hard=encounterSettings(HuntDifficulty.CHALLENGE,0f);assertTrue(easy.capacity<hard.capacity);assertTrue(easy.spawnSeconds>hard.spawnSeconds);assertTrue(easy.speed<hard.speed);for(level in HuntDifficulty.entries){val max=encounterSettings(level,10000f);assertTrue(max.capacity<=9);assertTrue(max.speed<=.25f);assertTrue(max.spawnSeconds>=2f);assertTrue(encounterSettings(level,39f).resting);assertFalse(encounterSettings(level,46f).resting)}}
 @Test fun earlyTargetsAreInFrontAndRearUnlocksLater(){for(level in HuntDifficulty.entries){assertTrue(encounterSettings(level,0f).minForwardDot>=0f);assertEquals(-1f,encounterSettings(level,100f).minForwardDot,0f)}}
 @Test fun attackPreparationsDoNotOverlapAcrossEnemies(){val b=AttackBudget();assertTrue(b.acquire(5f,1.65f));assertFalse(b.acquire(5f,1.65f));assertFalse(b.acquire(6f,1.65f));assertTrue(b.acquire(6.7f,1.65f));b.reset();assertTrue(b.acquire(0f,1.65f))}
 @Test fun shotAccuracyCountsMultiHitOnceAndRejectsInventedIds(){val e=HuntEngine();e.start();val first=e.recordShot();e.recordShot();assertTrue(e.creditShot(first));assertFalse(e.creditShot(first));assertFalse(e.creditShot(10000));assertEquals(2,e.shotsFired);assertEquals(1,e.shotsHit);assertEquals(.5f,e.accuracy(),.001f)}
 @Test fun practiceCannotDamagePlayerOrPolluteMissionResults(){val e=HuntEngine();e.startPractice();assertEquals(HuntPhase.PRACTICE,e.phase);assertFalse(e.hurt());assertEquals(0,e.recordShot());val t=e.spawn(3,V3(0f,0f,-2f));e.reveal(t.id);assertEquals(HitOutcome.KILLED,e.hit(t.id,2));assertEquals(1,e.practiceHits);assertEquals(0,e.kills);assertEquals(0,e.shotsFired);e.start();assertEquals(0,e.practiceHits);assertTrue(e.threats.isEmpty());assertEquals(3,e.lives)}
 @Test fun armorNeedsMultipleHitsAndWebSlowExpires(){val e=HuntEngine();e.start();val t=e.spawn(3,V3(0f,0f,-2f),4);e.reveal(t.id);assertEquals(HitOutcome.DAMAGED,e.hit(t.id,1,3f));assertEquals(3,t.health);assertEquals(3f,t.slowRemaining,.001f);e.tick(1f);assertEquals(2f,t.slowRemaining,.001f);assertEquals(HitOutcome.KILLED,e.hit(t.id,3));assertEquals(HitOutcome.NONE,e.hit(t.id,3));assertEquals(1,e.kills)}
 @Test fun trapKillsAreSeparateFromShootingAccuracy(){val e=HuntEngine();e.start();val t=e.spawn(0,V3(0f,0f,-2f));e.reveal(t.id);assertEquals(HitOutcome.KILLED,e.hit(t.id,2,trap=true));assertEquals(1,e.trapKills);assertEquals(0,e.shotsFired);assertEquals(0,e.shotsHit)}
 @Test fun weaponRolesAndArmorDiffer(){assertTrue(weaponRule(0).slowSeconds>0);assertEquals(0f,weaponRule(1).radius,0f);assertEquals(3f,weaponRule(3).range,0f);assertTrue(weaponRule(3).radius>1f);assertTrue(creatureHealth(3,HuntDifficulty.STANDARD)>creatureHealth(0,HuntDifficulty.STANDARD));assertTrue(creatureSpeedFactor(0)>creatureSpeedFactor(3))}
 @Test fun pulseAreaDoesNotDamageEnemiesBehindAnyPhysicalSurface(){val r=RoomSurfaceRegistry();r.replace(listOf(RoomSurface("wall",RoomSurfaceKind.WALL,V3(0f,0f,-.5f),Q4(0f,0f,0f,1f),listOf(V3(-2f,-2f,0f),V3(2f,-2f,0f),V3(0f,2f,0f)),listOf(0,1,2))));assertEquals(listOf(1),areaTargets(V3(0f,0f,0f),1.1f,listOf(1 to V3(.2f,0f,-.2f),2 to V3(0f,0f,-.8f),3 to V3(3f,0f,0f)),r))}
}
